class Solution {
  public String resultingString(String s) {
    char[] stack = new char[s.length()];
    int sp = 0;
    for (int i = 0; i < s.length(); i++) {
      char c = s.charAt(i);
      if (sp > 0) {
        int d = Math.abs(stack[sp - 1] - c);
        if (d == 1 || d == 25) {
          sp--;
          continue;
        }
      }
      stack[sp++] = c;
    }
    return new String(stack, 0, sp);
  }
}
